export type QuantumState = "stable" | "superposé";

export interface Sprite {
  readonly nom:              string;
  readonly couleur:          string;   // hex
  readonly vitesse_rotation: number;   // deg/s (negative = counter-clockwise)
  readonly distance_centre:  number;   // px orbital radius
  readonly angle:            number;   // 0–360°
  readonly taille:           number;   // px radius
  readonly opacite:          number;   // 0.0–1.0
  readonly etat_quantique:   QuantumState;
}

export const SPRITES_DEFAULT: readonly Sprite[] = Object.freeze([
  { nom: "Aether",  couleur: "#FF6B9D", vitesse_rotation:  30, distance_centre: 100, angle:   0, taille: 12, opacite: 1, etat_quantique: "stable" },
  { nom: "Lumina",  couleur: "#4ECDC4", vitesse_rotation: -45, distance_centre: 150, angle: 120, taille: 10, opacite: 1, etat_quantique: "stable" },
  { nom: "Solaris", couleur: "#FFE66D", vitesse_rotation:  20, distance_centre:  80, angle: 240, taille:  8, opacite: 1, etat_quantique: "stable" },
]);

